const results = await Promise.allSettled([
  tools.exec_command({cmd:"rtk git status --short","workdir":"/home/diogenes/Projects/twyne","max_output_tokens":1000}),
  tools.exec_command({cmd:"rtk sed -n '650,830p' src/components/onboarding/anti-tabula-rasa.tsx","workdir":"/home/diogenes/Projects/twyne","max_output_tokens":6000}),
  tools.exec_command({cmd:"rtk sed -n '1,140p' /home/diogenes/.codex/memories/MEMORY.md","workdir":"/home/diogenes/Projects/twyne","max_output_tokens":3000}),
  tools.exec_command({cmd:"rtk rg -n \"brief.*version|version.*brief|revision|revisions|draftTitle|title\" src/components/brief src/components/onboarding src/routes | head -n 100","workdir":"/home/diogenes/Projects/twyne","max_output_tokens":4000})
]);
for (let i=0;i<results.length;i++) text(JSON.stringify({i,...results[i]}));

